create extension if not exists pgcrypto;
create table public.allowed_emails(email text primary key,active boolean not null default true,added_by uuid,created_at timestamptz default now());
create table public.users(id uuid primary key references auth.users on delete cascade,email text unique not null,display_name text not null,roles text[] not null default '{siswa}',active boolean not null default true,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.profiles(user_id uuid primary key references public.users on delete cascade,bio text default '',github_url text default '',student_number text default '',school_class text default '',updated_at timestamptz default now());
create table public.classes(id text primary key,name text not null,description text default '',period text not null,timezone text default 'Asia/Jakarta',membership_version int default 0,archived_at timestamptz,created_at timestamptz default now(),updated_at timestamptz);
create table public.class_teachers(class_id text references public.classes on delete cascade,teacher_id uuid references public.users on delete cascade,active boolean default true,assigned_at timestamptz default now(),primary key(class_id,teacher_id));
create table public.class_members(class_id text references public.classes on delete cascade,student_id uuid references public.users on delete cascade,display_name text not null,school_class text default '',active boolean default true,joined_at timestamptz default now(),primary key(class_id,student_id));
create table public.materials(id uuid primary key default gen_random_uuid(),class_id text references public.classes on delete cascade,author_id uuid references public.users,title text not null,summary text default '',body text not null,topic text default 'Umum',link text default '',drive_url text default '',drive_embed_url text default '',status text default 'draft',created_at timestamptz default now(),updated_at timestamptz default now(),published_at timestamptz);
create table public.attachments(id uuid primary key default gen_random_uuid(),material_id uuid references public.materials on delete cascade,storage_path text unique not null,original_name text not null,content_type text not null,size int not null,created_at timestamptz default now());
create table public.meetings(id uuid primary key default gen_random_uuid(),class_id text references public.classes on delete cascade,title text not null,location text default '',material_ids uuid[] default '{}',starts_at timestamptz not null,ends_at timestamptz not null,opens_at timestamptz not null,late_after timestamptz not null,closes_at timestamptz not null,created_by uuid references public.users,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.attendance_sessions(meeting_id uuid primary key references public.meetings on delete cascade,class_id text references public.classes,state text not null,opens_at timestamptz not null,closes_at timestamptz not null,late_after timestamptz not null,active_token_hash text,qr_version int default 0,participant_count int default 0,roster_ready boolean default false,opened_at timestamptz default now(),closed_at timestamptz,finalized_at timestamptz);
create table public.meeting_participants(meeting_id uuid references public.meetings on delete cascade,student_id uuid references public.users,display_name text not null,school_class text default '',primary key(meeting_id,student_id));
create table public.qr_tokens(token_hash text primary key,meeting_id uuid references public.meetings on delete cascade,class_id text references public.classes,version int not null,generated_by uuid references public.users,created_at timestamptz default now(),expires_at timestamptz not null,revoked_at timestamptz,purge_at timestamptz not null);
create table public.attendance(id uuid primary key default gen_random_uuid(),meeting_id uuid references public.meetings on delete cascade,class_id text references public.classes,student_id uuid references public.users,display_name text not null,school_class text default '',meeting_title text not null,meeting_starts_at timestamptz not null,status text not null,checked_in_at timestamptz,source text not null,qr_version int,recorded_by text not null,updated_at timestamptz default now(),unique(meeting_id,student_id));
do $$ declare t text; begin foreach t in array array['allowed_emails','users','profiles','classes','class_teachers','class_members','materials','attachments','meetings','attendance_sessions','meeting_participants','qr_tokens','attendance'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
insert into storage.buckets(id,name,public,file_size_limit) values('materials','materials',false,20971520) on conflict(id) do update set public=false,file_size_limit=20971520;
create or replace function public.secure_check_in(p_student uuid,p_token_hash text) returns jsonb language plpgsql security definer set search_path=public as $$ declare t qr_tokens;s attendance_sessions;m meetings;p meeting_participants;a attendance;ts timestamptz=clock_timestamp();begin select * into t from qr_tokens where token_hash=p_token_hash for update;if not found then raise exception 'QR_INVALID';end if;select * into s from attendance_sessions where meeting_id=t.meeting_id for update;if s.state<>'open' or ts>=s.closes_at or ts>=t.expires_at or t.revoked_at is not null or s.active_token_hash<>p_token_hash then raise exception 'QR_INVALID';end if;select * into a from attendance where meeting_id=t.meeting_id and student_id=p_student;if found then return jsonb_build_object('code','ALREADY_RECORDED','record',to_jsonb(a));end if;perform 1 from class_members where class_id=t.class_id and student_id=p_student and active;if not found then raise exception 'NOT_ELIGIBLE';end if;select * into p from meeting_participants where meeting_id=t.meeting_id and student_id=p_student;if not found then raise exception 'NOT_ELIGIBLE';end if;select * into m from meetings where id=t.meeting_id;insert into attendance(meeting_id,class_id,student_id,display_name,school_class,meeting_title,meeting_starts_at,status,checked_in_at,source,qr_version,recorded_by)values(m.id,m.class_id,p_student,p.display_name,p.school_class,m.title,m.starts_at,case when ts<=s.late_after then 'hadir' else 'terlambat' end,ts,'qr',t.version,p_student::text)returning * into a;return jsonb_build_object('code','SUCCESS','record',to_jsonb(a));end $$;revoke all on function public.secure_check_in(uuid,text) from public,anon,authenticated;grant execute on function public.secure_check_in(uuid,text) to service_role;
